steps.starterCode:
from langchain_core.tools import tool

@tool
def calculate(expr: str) -> str:
    """计算数学表达式"""
    return str(eval(expr))

@tool
def search(query: str) -> str:
    """搜索"""
    return f'结果: {query}'

tools = {'calculate': calculate, 'search': search}

# 规则路由: 根据关键词
def rule_route(question: str) -> str:
    if any(kw in question for kw in ['计算', '加减', '乘除']):
        return tools['calculate'].invoke({'expr': '2+3'})
    elif any(kw in question for kw in ['搜索', '查找']):
        return tools['search'].invoke({'query': question})
    return '无法路由'

print(rule_route('计算 2+3'))
print(rule_route('搜索 python'))

# 总结: 规则路由快但死板, Agent路由灵活但慢
print('规则路由: 快, 准确, 但需预设规则')
print('Agent路由: 灵活, 自动, 但耗 token')

